const items = $input.all();
const totalAmount = items.reduce((s, i) => s + i.json.amount, 0);
const totalWeighted = items.reduce((s, i) => s + i.json.weightedAmount, 0);
const totalCommission = items.reduce((s, i) => s + i.json.commission, 0);
const byRep = {};
items.forEach(i => { const rep = i.json.salesRep; if (!byRep[rep]) byRep[rep] = { deals: 0, amount: 0 }; byRep[rep].deals++; byRep[rep].amount += i.json.amount; });
const lines = items.map(i => `${i.json.customer}  $${i.json.amount.toLocaleString()}  [${i.json.stage}]`);
const repLines = Object.entries(byRep).map(([rep, d]) => `${rep}：${d.deals} 筆`);
const report = ['== Pipeline 報表 ==', `商機：${items.length} 筆`, `總額：$${totalAmount.toLocaleString()}`, `加權：$${totalWeighted.toLocaleString()}`, `佣金：$${totalCommission.toLocaleString()}`, '-- 業務 --', ...repLines, '-- 明細 --', ...lines].join('\n');
return [{ json: { totalDeals: items.length, totalAmount, totalWeighted, totalCommission, report }}];
